import { useEffect, useRef, useState } from 'react';
import { Check, Copy, KeyRound, Plus, TriangleAlert } from 'lucide-react';
import toast from 'react-hot-toast';
import { Button, Card, cx } from '../../components/common/ui';
import { handoverText } from '../../utils/platformForm';

/**
 * The one and only sight of a new pharmacy's credentials.
 *
 * The temporary password is generated by the server, returned once, and stored nowhere — not hashed-and-shown,
 * not logged, not emailed. If it is lost between this screen and the pharmacy, nobody can look it up; somebody
 * has to reset the account. So this panel is built around that single fact: it says so plainly, it makes copying
 * the easy thing to do, and it will not let itself be dismissed until the operator says the handover is done.
 *
 * That last bit is deliberate friction. It is the only guard against the ordinary mistake — reading the panel,
 * being interrupted, and clicking on — and it costs one click in exchange for not stranding a pharmacy.
 */
export default function CredentialsHandover({ created, onDone }) {
  const [copied, setCopied] = useState('');
  const [acknowledged, setAcknowledged] = useState(false);
  const headingRef = useRef(null);
  const timer = useRef(null);

  const signInUrl = `${window.location.origin}/login`;
  const note = handoverText({ ...created, signInUrl });

  // Land on the heading, not at the top of the page: this is why the screen changed.
  useEffect(() => {
    headingRef.current?.focus();
    return () => clearTimeout(timer.current);
  }, []);

  const copy = async (what, text) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(what);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(''), 2500);
    } catch {
      // Refused in an insecure context, or blocked. The values are on screen and selectable, so say that.
      toast.error('The browser would not let me copy. Select the text and copy it by hand.');
    }
  };

  const row = (key, label, value, mono = 'font-mono') => (
    <div className="flex items-start justify-between gap-3 border-t border-warning/25 py-2.5 first:border-t-0">
      <div className="min-w-0">
        <dt className="text-[11px] font-bold uppercase tracking-wide text-muted">{label}</dt>
        <dd className={cx('mt-0.5 break-all text-sm', mono)} data-testid={`new-org-${key}`}>
          {value}
        </dd>
      </div>
      <Button variant="secondary" size="sm" onClick={() => copy(key, value)} aria-label={`Copy ${label.toLowerCase()}`}>
        {copied === key ? <Check className="h-3.5 w-3.5" aria-hidden="true" /> : <Copy className="h-3.5 w-3.5" aria-hidden="true" />}
        {copied === key ? 'Copied' : 'Copy'}
      </Button>
    </div>
  );

  return (
    <Card className="p-5 sm:p-6">
      <div className="flex items-start gap-3">
        <div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-success-soft text-success">
          <Check className="h-5 w-5" aria-hidden="true" />
        </div>
        <div className="min-w-0">
          <h2 ref={headingRef} tabIndex={-1} className="text-lg font-bold tracking-tight outline-none">
            {created.organization.name} is set up
          </h2>
          <p className="mt-0.5 text-sm text-muted">Its five built-in roles were created, and the owner is its first administrator.</p>
        </div>
      </div>

      <section aria-labelledby="handover-title" className="mt-5 rounded-2xl border border-warning/40 bg-warning/10 p-4">
        <h3 id="handover-title" className="flex items-start gap-2 text-sm font-bold">
          <TriangleAlert className="mt-0.5 h-4 w-4 shrink-0 text-warning" aria-hidden="true" />
          Shown once. Copy these now — the password is stored nowhere and cannot be shown again.
        </h3>

        <dl className="mt-3">
          {row('url', 'Sign in at', signInUrl)}
          {row('email', 'Email', created.administrator.email, 'font-mono font-semibold')}
          {row('password', 'Temporary password', created.temporaryPassword, 'select-all font-mono text-base font-bold tracking-wide')}
        </dl>

        <div className="mt-3 border-t border-warning/25 pt-3">
          <Button onClick={() => copy('all', note)} className="w-full sm:w-auto">
            {copied === 'all' ? <Check className="h-4 w-4" aria-hidden="true" /> : <Copy className="h-4 w-4" aria-hidden="true" />}
            {copied === 'all' ? 'Copied the whole message' : 'Copy the whole message'}
          </Button>
          <p role="status" aria-atomic="true" className="mt-2 min-h-4 text-xs text-success">
            {copied ? 'Copied to the clipboard.' : ''}
          </p>
        </div>
      </section>

      <p className="mt-4 text-xs text-muted">{created.note}</p>

      <div className="mt-4 rounded-xl border border-line bg-subtle/50 p-3.5">
        <label className="flex cursor-pointer items-start gap-2.5 text-sm font-semibold">
          <input
            type="checkbox"
            checked={acknowledged}
            onChange={(e) => setAcknowledged(e.target.checked)}
            className="mt-0.5 h-4 w-4 shrink-0 cursor-pointer accent-[var(--primary)] focus-visible:ring-2 focus-visible:ring-primary/40"
          />
          I have sent these to the pharmacy.
        </label>
        <Button onClick={onDone} disabled={!acknowledged} className="mt-3">
          <Plus className="h-4 w-4" aria-hidden="true" /> Onboard another
        </Button>
        {!acknowledged && (
          <p className="mt-2 flex items-start gap-1.5 text-xs text-muted">
            <KeyRound className="mt-0.5 h-3.5 w-3.5 shrink-0" aria-hidden="true" />
            Leaving this panel is the last chance to read the password.
          </p>
        )}
      </div>
    </Card>
  );
}
